    46  void ObjectMapper::write(data::stream::ConsistentOutputStream* stream, const oatpp::Void& variant, data::mapping::ErrorStack& errorStack) const {
    47
    48    /* if variant is Tree - we can serialize it right away */
    49    if(variant.getValueType() == oatpp::Tree::Class::getType()) {
    50      auto tree = static_cast<const data::mapping::Tree*>(variant.get());
    51      writeTree(stream, *tree, errorStack);
    52      return;
    53    }
    54
    55    data::mapping::Tree tree;
    56    data::mapping::ObjectToTreeMapper::State state;
    57
    58    state.config = &m_serializerConfig.mapper;
    59    state.tree = &tree;
    60
    61    m_objectToTreeMapper.map(state, variant);
    62    if(!state.errorStack.empty()) {
    63      errorStack = std::move(state.errorStack);
    64      return;
    65    }
    66
    67    writeTree(stream, tree, errorStack);
    68
