   167  void Deserializer::deserialize(State& state) {
   168
   169    state.caret->skipBlankChars();
   170
   171    auto c = *state.caret->getCurrData();
   172    switch (c) {
   173      case 'n':
   174        deserializeNull(state);
   175        break;
   176      case '{':
   177        deserializeMap(state);
   178        break;
   179      case '[':
   180        deserializeArray(state);
   181        break;
   182      case '"':
   183        deserializeString(state);
   184        break;
   185      case 't':
   186      case 'f':
   187        deserializeBoolean(state);
   188        break;
   189      case '-':
   190      case '0':
   191      case '1':
   192      case '2':
   193      case '3':
   194      case '4':
   195      case '5':
   196      case '6':
   197      case '7':
   198      case '8':
   199      case '9':
   200        deserializeNumber(state);
   201        break;
   202      default:
   203        state.errorStack.push("[json]: Unknown character.");
   204        break;
   205    }
